cat > nginx.conf <<'EOF'
# nginx config for serving the static Astro build on Fly.io.
# Fly's edge terminates TLS and forwards plain HTTP to port 8080.

user  nginx;
worker_processes  auto;
pid   /var/run/nginx.pid;

# Everything goes to stdout/stderr so `fly logs` picks it up.
error_log  /dev/stderr warn;

events {
    worker_connections  1024;
}

http {
    include       /etc/nginx/mime.types;
    default_type  application/octet-stream;

    # One JSON object per request: easy to read in `fly logs` and to search/ship.
    # Fly-Client-IP carries the real visitor IP (remote_addr is Fly's proxy).
    log_format json escape=json
      '{"time":"$time_iso8601",'
      '"client_ip":"$http_fly_client_ip",'
      '"method":"$request_method",'
      '"uri":"$request_uri",'
      '"status":$status,'
      '"bytes":$body_bytes_sent,'
      '"duration_ms":$request_time,'
      '"referer":"$http_referer",'
      '"user_agent":"$http_user_agent",'
      '"fly_region":"$http_fly_region",'
      '"request_id":"$http_fly_request_id"}';
    access_log  /dev/stdout  json;

    sendfile        on;
    tcp_nopush      on;
    keepalive_timeout  65;
    server_tokens   off;

    gzip  on;
    gzip_vary  on;
    gzip_comp_level  6;
    gzip_min_length  256;
    gzip_types  text/css text/plain text/xml application/javascript
                application/json application/xml application/rss+xml image/svg+xml;

    # Cache policy by path. Defined here (not with add_header inside locations)
    # so the security headers below are never dropped by nginx's add_header
    # inheritance rules.
    map $uri $cache_control {
        ~^/_astro/       "public, max-age=31536000, immutable";  # content-hashed assets
        ~\.html$         "public, max-age=0, must-revalidate";
        ~/$              "public, max-age=0, must-revalidate";
        /rss.xml         "public, max-age=300";
        default          "public, max-age=3600";
    }

    server {
        listen       8080 default_server;
        listen       [::]:8080 default_server;
        server_name  _;
        root         /usr/share/nginx/html;

        # Fly terminates TLS, so redirects (e.g. /about -> /about/) must be
        # relative or they'd point at http://<host>:8080/.
        absolute_redirect  off;

        add_header  Cache-Control              $cache_control always;
        add_header  Strict-Transport-Security  "max-age=31536000" always;
        add_header  X-Content-Type-Options     "nosniff" always;
        add_header  X-Frame-Options            "SAMEORIGIN" always;
        add_header  Referrer-Policy            "strict-origin-when-cross-origin" always;

        # Health check endpoint for Fly (fly.toml) and Docker HEALTHCHECK.
        location = /healthz {
            access_log  off;
            default_type  text/plain;
            return 200 "ok\n";
        }

        location / {
            try_files  $uri $uri/ $uri.html =404;
        }
    }
}
EOF

