    }
''','''        default          "public, max-age=3600";
    }
    # Only cache successful responses; never cache 404s, redirects or errors.
    map $status $cache_control {
        200      $cache_control_by_path;
        304      $cache_control_by_path;
        default  "no-store";
    }
''')
